Execute the appropriate customer operation using the available tools.

parameters.jsCode:
// Format SW5 response for Router
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json;
const inputData = $('When Executed by Another Workflow').first().json;

// If AI returned structured response, use it
if (aiOutput.workflow === 'SW5') {
  return [{
    json: aiOutput
  }];
}

// Otherwise, build structured response
let response = {
  workflow: 'SW5',
  operation: 'unknown',
  success: true,
  data: null,
  summary: '',
  error: null
};

// Try to parse AI output
if (typeof aiOutput === 'string') {
  try {
    const parsed = JSON.parse(aiOutput);
    response = { ...response, ...parsed };
  } catch (e) {
    response.summary = aiOutput;
  }
} else if (typeof aiOutput === 'object') {
  response = { ...response, ...aiOutput };
}

// Infer operation type from query if not set
const query = (inputData.query || '').toLowerCase();
if (!response.operation || response.operation === 'unknown') {
  if (query.includes('list customers') || query.includes('show customers')) {
    response.operation = 'list_customers';
  } else if (query.includes('get customer') || inputData.customer_id) {
    response.operation = 'get_customer';
  } else if (query.includes('find customer') || query.includes('search')) {
    response.operation = 'search_customers';
  } else if (query.includes('tickets for') || query.includes('ticket history')) {
    response.operation = 'get_customer_tickets';
  } else if (query.includes('how many tickets') || query.includes('customer stats')) {
    response.operation = 'customer_analytics';
  }
}

return [{
  json: response
}];

// Log API call to Supabase
const items = $input.all();
const inputData = $('When Executed by Another Workflow').first().json;
const response = items[0].json;

const logEntry = {
  workflow_id: 'SW5',
  run_id: $execution.id,
  node_name: 'SW5_AI_Agent',
  direction: 'response',
  method: response.operation || 'customer_ops',
  url: `${$vars.GORGIAS_BASE_URL}/api/customers`,
  status_code: response.success ? 200 : 500,
  request_body: JSON.stringify(inputData),
  response_body: JSON.stringify(response.data || response.summary),
  error_message: response.error || null,
  actor_user: inputData.user || null,
  channel: inputData.channel || null,
  thread_ts: inputData.thread_ts || null,
  ticket_id: inputData.ticket_id || null,
  tags: [],
  duration_ms: null,
  extra: JSON.stringify({
    operation: response.operation,
    customer_id: inputData.customer_id,
    customer_email: inputData.customer_email
  })
};

return [{
  json: logEntry
}];
